import{_ as e,o as a,c as r,a5 as d}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"六方晶系","description":"","frontmatter":{"title":"六方晶系","crystalSystem":"hexagonal"},"headers":[],"relativePath":"zh/classification/crystal-systems/hexagonal.md","filePath":"zh/classification/crystal-systems/hexagonal.md","lastUpdated":1790876393000}'),l={name:"zh/classification/crystal-systems/hexagonal.md"};function n(s,t,i,o,h,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="六方晶系" tabindex="-1">六方晶系 <a class="header-anchor" href="#六方晶系" aria-label="Permalink to &quot;六方晶系&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>六方晶系（严格按四轴米勒指数）三条水平轴等长、互成 120°，纵向 c 轴与水平轴正交。晶体为一轴晶。绿柱石族以典型六方柱晶形为其 代表。注意：部分参考资料将三方晶系归入六方晶系之下。</p><h2 id="晶体学参数" tabindex="-1">晶体学参数 <a class="header-anchor" href="#晶体学参数" aria-label="Permalink to &quot;晶体学参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>值</th></tr></thead><tbody><tr><td>晶轴</td><td>a₁ = a₂ = a₃ ≠ c (4-index notation)</td></tr><tr><td>夹角</td><td>120° / 120° / 120° between lateral axes, 90° vertical</td></tr><tr><td>对称性等级</td><td>medium-high</td></tr><tr><td>光学分类</td><td>uniaxial</td></tr><tr><td>光性</td><td>+ or −</td></tr><tr><td>双折射率范围</td><td>0.000–0.180</td></tr><tr><td>解理</td><td>poor / none</td></tr><tr><td>常见晶形</td><td>六方柱、六方双锥</td></tr></tbody></table><h2 id="主要宝石" tabindex="-1">主要宝石 <a class="header-anchor" href="#主要宝石" aria-label="Permalink to &quot;主要宝石&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>折射率</th><th>比重</th></tr></thead><tbody><tr><td>Emerald (Beryl)</td><td>1.565–1.602</td><td>2.67–2.78</td></tr><tr><td>Aquamarine</td><td>1.564–1.596</td><td>2.66–2.80</td></tr><tr><td>Morganite</td><td>1.560–1.600</td><td>2.71–2.90</td></tr><tr><td>Heliodor</td><td>1.564–1.595</td><td>2.68</td></tr><tr><td>Apatite</td><td>1.628–1.650</td><td>3.16–3.22</td></tr><tr><td>Sugilite</td><td>1.607–1.638</td><td>2.74</td></tr><tr><td><em>详见<a href="./../intro.html">分类总览</a>。</em></td><td></td><td></td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.open.edu/openlearn/science-maths-technology/an-introduction-minerals-and-rocks-under-the-microscope/content-section-1.6.3/?tip=linktip" target="_blank" rel="noreferrer">Open University：晶体系统</a><span>晶系、晶轴关系与对称性基础</span><small>打开来源 ↗</small></li><li><a href="https://australian.museum/learn/minerals/what-are-minerals/crystallography/" target="_blank" rel="noreferrer">Australian Museum：晶体学</a><span>晶体结构与矿物学分类背景</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/summer-2025-phenomenal-gemstones" target="_blank" rel="noreferrer">GIA：现象宝石的结构</a><span>宝石学中的结构与光学观察线索</span><small>打开来源 ↗</small></li></ul></aside>',8)])])}const u=e(l,[["render",n]]);export{p as __pageData,u as default};
